-- ============================================================================
--  analysis_insights.insight_templates seed — 'Commons' tab (commons).
--
--  Purpose-scoped slice of the registry (the sibling 01_ DDL carries the
--  table + the resolution contract). This file is the TAB'S source of
--  truth: applying it re-syncs the tab (DELETE its rows, INSERT these).
--  Rows are ordered by TRADING VALUE within each page (ordinal = the
--  Ask AI modal's display order — the most decision-relevant metric
--  first); template_id = analysis.commons.<page>.<metric>.
--
--  DESCRIPTION STYLE (2026-10-27): every description is written as an
--  AI-prompt fragment, not a narrative — what the metric measures
--  financially, how to read/act on it (side, trigger, exit timing), and
--  any quoted threshold carrying a rarity/attention parenthesis. No UI
--  wording, no navigation verbs.
-- ============================================================================

DELETE FROM analysis_insights.insight_templates WHERE tab = 'commons';

