    -- ma-spread · MA-Spread [scope=security]
    ('analysis.commons.ma-spread.close', 'commons', 'ma-spread', 'close', 'Close', '', 'Close price at the as-of date — the anchor every gap and level metric on this page is quoted against.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "compute", "fn": "close"}}'::jsonb, 0),
    ('analysis.commons.ma-spread.chg_20d', 'commons', 'ma-spread', 'chg_20d', '20d change', '%', '20-session close change — the monthly momentum gauge: sign = trend direction, double-digit magnitude marks a trending (not range) tape.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "compute", "fn": "pct_change", "args": {"days": 20}}}'::jsonb, 1),
    ('analysis.commons.ma-spread.trend_state', 'commons', 'ma-spread', 'trend_state', 'Trend state', '', 'Signals-tier trend day state at the as-of date: 0 top (MA255-gap extreme high) | 1 bottom | 2 rise (RSI re-entry up) | 3 fall | 5 none. The regime context every signal family conditions on — quote it first.', '{"scope": "security", "rank": false, "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.trend_days", "value": "trend", "date": "date", "code": "code", "sec_type": "sec_type"}, "sec_types": ["etf", "index", "stock"]}'::jsonb, 2),
    ('analysis.commons.ma-spread.price_vs_ma60', 'commons', 'ma-spread', 'price_vs_ma60', 'Price vs MA60', '', '(close/MA60 - 1) signed fraction — the quarterly swing anchor and the ma60-cross buy / MA60-reclaim trigger level. Positive = extended above the quarterly anchor (momentum); negative = discount (reclaim-buy watch).', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_spreads_detail", "value": "price_vs_ma60", "date": "date", "code": "code", "sec_type": "sec_type"}, "compute": {"fn": "ma_gap_pct", "args": {"window": 60}}}'::jsonb, 3),
    ('analysis.commons.ma-spread.price_vs_ma255', 'commons', 'ma-spread', 'price_vs_ma255', 'Price vs MA255', '', '(close/MA255 - 1) signed fraction — the yearly anchor gap; its trailing extremes define the top/bottom trend states. Far above = stretched yearly gap (extension risk), far below = deep discount (capitulation watch).', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_spreads_detail", "value": "price_vs_ma255", "date": "date", "code": "code", "sec_type": "sec_type"}}'::jsonb, 4),
    ('analysis.commons.ma-spread.price_vs_ma20', 'commons', 'ma-spread', 'price_vs_ma20', 'Price vs MA20', '', '(close/MA20 - 1) signed fraction — the monthly anchor and the Bollinger z numerator; persistently positive = the band-walk regime.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_spreads_detail", "value": "price_vs_ma20", "date": "date", "code": "code", "sec_type": "sec_type"}}'::jsonb, 5),
    ('analysis.commons.ma-spread.ma5_vs_ma20', 'commons', 'ma-spread', 'ma5_vs_ma20', 'MA5 vs MA20', '', '(MA5/MA20 - 1) signed fraction — the fast MA pair spread; sign flips mark the short-term reclaim/breakdown events the ma20-cross family trades.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_spreads_detail", "value": "ma5_vs_ma20", "date": "date", "code": "code", "sec_type": "sec_type"}}'::jsonb, 6),
    ('analysis.commons.ma-spread.rsi_14d', 'commons', 'ma-spread', 'rsi_14d', 'RSI14', '', '14-day Wilder RSI (0-100). >70 extended (exit-timing watch — overbought persists under drift-up), <30 washed-out (capitulation-buy watch). The repo''s own triggers use per-code trailing percentile tails, never these fixed levels.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_rsi", "value": "rsi_14days", "date": "date", "code": "code", "sec_type": "sec_type"}, "compute": {"fn": "wilder_rsi", "args": {"window": 14}}}'::jsonb, 7),
    ('analysis.commons.ma-spread.rsi_10d', 'commons', 'ma-spread', 'rsi_10d', 'RSI10', '', '10-day Wilder RSI — the measured best capitulation-buy window (per-code bottom-1% trailing tail: pooled +1.91% @72% hit; the tail holds ~1% of days — rare, high attention when breached).', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_rsi", "value": "rsi_10days", "date": "date", "code": "code", "sec_type": "sec_type"}, "compute": {"fn": "wilder_rsi", "args": {"window": 10}}}'::jsonb, 8),
    ('analysis.commons.ma-spread.rsi_6d', 'commons', 'ma-spread', 'rsi_6d', 'RSI6', '', '6-day Wilder RSI — the short entry window of the RSI-tail grid (14/10/6); fastest to react, noisiest of the three.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_rsi", "value": "rsi_6days", "date": "date", "code": "code", "sec_type": "sec_type"}, "compute": {"fn": "wilder_rsi", "args": {"window": 6}}}'::jsonb, 9),
    ('analysis.commons.ma-spread.momentum_20d', 'commons', 'ma-spread', 'momentum_20d', 'Momentum 20d', '', 'Fixed-anchor 20-day fractional momentum (signed) — the monthly continuation gauge; its log-return tails are the momentum family''s triggers.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_momentum", "value": "momentum_20days", "date": "date", "code": "code", "sec_type": "sec_type"}}'::jsonb, 10),
    ('analysis.commons.ma-spread.momentum_long_lb', 'commons', 'ma-spread', 'momentum_long_lb', 'Momentum @long lb', '', 'Momentum at the day''s adaptive long lookback (targets a 12% move, clipped 60-255d) — the slow axis that stays comparable across vol regimes.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_momentum", "value": "momentum_long", "date": "date", "code": "code", "sec_type": "sec_type"}}'::jsonb, 11),
    ('analysis.commons.ma-spread.roof_est_255', 'commons', 'ma-spread', 'roof_est_255', 'Est roof 255d', '', 'Cross-method consensus (median) estimated resistance at the 255d window — the rf_break roof trigger. Deep closes past it (1-3%+ above) measured a continuation BUY (monotone in depth); shallow touches drift up — the roof anchors support, never a sell.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_spreads_roof_floor_estimates", "value": "roof_estimate", "date": "date", "code": "code", "sec_type": "sec_type", "match": {"period": 255, "method": 5}}}'::jsonb, 12),
    ('analysis.commons.ma-spread.floor_est_255', 'commons', 'ma-spread', 'floor_est_255', 'Est floor 255d', '', 'Cross-method consensus (median) estimated support at the 255d window — the rf_break floor trigger. Deep breaks (2-5% below) measured a capitulation V-bottom BUY, the deeper the harder the bounce; shallow pierces carry no edge.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_spreads_roof_floor_estimates", "value": "floor_estimate", "date": "date", "code": "code", "sec_type": "sec_type", "match": {"period": 255, "method": 5}}}'::jsonb, 13),
    ('analysis.commons.ma-spread.amt_share_vs_ma20', 'commons', 'ma-spread', 'amt_share_vs_ma20', 'Amt share vs MA20', '', 'Trading-amount market share relative to its own MA20 — the liquidity trend behind price: rising = attention accumulating, falling = fading participation discounting the move''s conviction.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_spreads_detail", "value": "trading_amt_market_share_vs_ma20", "date": "date", "code": "code", "sec_type": "sec_type"}}'::jsonb, 14),
    ('analysis.commons.ma-spread.band_hi_255_10', 'commons', 'ma-spread', 'band_hi_255_10', 'Band high 255d', '', 'Top edge of the trailing 255d high-low band (90th percentile) — yearly resistance context; closes pressing it are the band-walk/top test.', '{"scope": "security", "page_title": "MA-Spread", "source": {"kind": "table", "table": "analysis.mov_ave_high_low_pct", "value": "high_val", "date": "date_year_month", "code": "code", "sec_type": "sec_type", "match": {"period": 255, "pct_type": 10}}}'::jsonb, 15),
